import json, pathlib, work
policy=json.loads(pathlib.Path('policy.json').read_text())
requests=json.loads(pathlib.Path('requests.json').read_text())
actual=[work.evaluate(request, policy) for request in requests]
report=json.loads(pathlib.Path('report.json').read_text())
assert report == actual, (report, actual)
assert work.evaluate({'layers':[{'enabled':False},{'retries':0},{'label':''}]}, policy) == {'ok':True,'config':{'enabled':False,'retries':0,'label':''},'error':None}
assert work.evaluate({'layers':[{'extra':1}]}, policy) == {'ok':False,'config':{},'error':'unknown_key'}
assert work.evaluate({'layers':[{'retries':True}]}, policy) == {'ok':False,'config':{},'error':'type'}
assert work.evaluate({'layers':[{'retries':None}]}, policy) == {'ok':False,'config':{},'error':'type'}
assert work.evaluate({'environment':{'retries':'4'}}, policy) == {'ok':False,'config':{},'error':'environment'}
print('report and policy checks passed')
